SELECT COUNT(*)
FROM book b
LEFT JOIN book_category c ON b.category_id = c.id


        AND b.isbn = #{isbn}


        AND b.name LIKE CONCAT('%', #{name}, '%')


        AND b.author LIKE CONCAT('%', #{author}, '%')


        AND b.category_id = #{categoryId}


        AND b.status = #{status}

SELECT b.*, c.name AS category_name
FROM book b
LEFT JOIN book_category c ON b.category_id = c.id


        AND b.isbn = #{bookQuerySelectDto.isbn}


        AND b.name LIKE CONCAT('%', #{bookQuerySelectDto.name}, '%')


        AND b.author LIKE CONCAT('%', #{bookQuerySelectDto.author}, '%')


        AND b.category_id = #{bookQuerySelectDto.categoryId}


        AND b.status = #{bookQuerySelectDto.status}


ORDER BY b.create_time DESC, b.id DESC
LIMIT #{BeginIndex}, #{bookQuerySelectDto.pageSize};

